<?php
require_once __DIR__.'/../../auth/auth_check.php';
require_once __DIR__.'/../../config/database.php';
$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare('SELECT * FROM rehabilitasi_das WHERE id=?');$stmt->execute([$id]);$r=$stmt->fetch();
if(!$r){http_response_code(404);exit('Data tidak ditemukan');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $nama=trim($_POST['nama_perusahaan']??'');$jenis=trim($_POST['jenis_kegiatan']??'');
  if($nama===''||$jenis===''){$error='Nama perusahaan dan jenis kegiatan wajib diisi.';}else{
    $st=$pdo->prepare('UPDATE rehabilitasi_das SET nomor_ippkh=?,nama_perusahaan=?,nomor_sk=?,tanggal_sk=?,jenis_kegiatan=?,luas_lahan=?,provinsi=?,kabupaten=?,kecamatan=?,desa=?,koordinat=?,status_kegiatan=?,keterangan=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');
    $st->execute([$_POST['nomor_ippkh']??'',$_POST['nama_perusahaan'],$_POST['nomor_sk']??'',$_POST['tanggal_sk']?:null,$_POST['jenis_kegiatan'],(float)($_POST['luas_lahan']??0),$_POST['provinsi']??'',$_POST['kabupaten']??'',$_POST['kecamatan']??'',$_POST['desa']??'',$_POST['koordinat']??'',$_POST['status_kegiatan']??'Diajukan',$_POST['keterangan']??',$id]);
    $pdo->prepare('INSERT INTO aktivitas_log (user_id,aksi,entitas,entitas_id,detail) VALUES (?,?,?,?,?)')->execute([$_SESSION['user_id'],'Mengubah','rehabilitasi_das',$id,'Data rehabilitasi diperbarui']);
    header('Location: detail.php?id='.$id);exit;
  }
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Rehabilitasi | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Rehabilitasi DAS</p><h1>Edit Data</h1></div><a class="btn btn-detail" href="detail.php?id=<?=$id?>">Kembali</a></div><div class="panel p-4"><form method="post" class="row g-3"><?php if($error):?><div class="col-12 alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><div class="col-md-6"><label class="form-label">Nomor IPPKH</label><input name="nomor_ippkh" class="form-control" value="<?=htmlspecialchars($r['nomor_ippkh'])?>"></div><div class="col-md-6"><label class="form-label">Nama Perusahaan</label><input name="nama_perusahaan" class="form-control" value="<?=htmlspecialchars($r['nama_perusahaan'])?>" required></div><div class="col-md-4"><label class="form-label">Nomor SK</label><input name="nomor_sk" class="form-control" value="<?=htmlspecialchars($r['nomor_sk'])?>"></div><div class="col-md-4"><label class="form-label">Tanggal SK</label><input type="date" name="tanggal_sk" class="form-control" value="<?=htmlspecialchars($r['tanggal_sk'])?>"></div><div class="col-md-4"><label class="form-label">Jenis Kegiatan</label><input name="jenis_kegiatan" class="form-control" value="<?=htmlspecialchars($r['jenis_kegiatan'])?>" required></div><div class="col-md-3"><label class="form-label">Luas (Ha)</label><input type="number" step="0.01" name="luas_lahan" class="form-control" value="<?=htmlspecialchars($r['luas_lahan'])?>"></div><div class="col-md-3"><label class="form-label">Provinsi</label><input name="provinsi" class="form-control" value="<?=htmlspecialchars($r['provinsi'])?>"></div><div class="col-md-3"><label class="form-label">Kabupaten</label><input name="kabupaten" class="form-control" value="<?=htmlspecialchars($r['kabupaten'])?>"></div><div class="col-md-3"><label class="form-label">Kecamatan</label><input name="kecamatan" class="form-control" value="<?=htmlspecialchars($r['kecamatan'])?>"></div><div class="col-md-4"><label class="form-label">Desa</label><input name="desa" class="form-control" value="<?=htmlspecialchars($r['desa'])?>"></div><div class="col-md-4"><label class="form-label">Koordinat</label><input name="koordinat" class="form-control" value="<?=htmlspecialchars($r['koordinat'])?>"></div><div class="col-md-4"><label class="form-label">Status</label><select name="status_kegiatan" class="form-select"><?php foreach(['Diajukan','Dalam Pelaksanaan','Selesai'] as $s):?><option <?=$r['status_kegiatan']===$s?'selected':''?>><?=htmlspecialchars($s)?></option><?php endforeach?></select></div><div class="col-12"><label class="form-label">Keterangan</label><textarea name="keterangan" class="form-control" rows="3"><?=htmlspecialchars($r['keterangan'])?></textarea></div><div class="col-12"><button class="btn btn-orange">Simpan Perubahan</button></div></form></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
